+        private IEnumerator FadeOutAudioRoutine(AudioSource src, float duration)
+        {
+            if (src == null) yield break;
+            float startVol = src.volume;
+            float t = 0f;
+            while (t < duration)
+            {
+                t += Time.deltaTime;
+                if (src != null) src.volume = Mathf.Lerp(startVol, 0f, t / duration);
+                yield return null;
+            }
