    }

    void PrintHierarchy(Transform t, string indent, ExecutionResult result)
    {
        var comps = t.GetComponents<Component>();
        string compList = "";
        foreach (var c in comps)
        {
            if (c != null) compList += c.GetType().Name + ", ";
        }
        var rt = t.GetComponent<RectTransform>();
        string rtInfo = rt != null ? $" pos={rt.anchoredPosition} size={rt.sizeDelta} anchorMin={rt.anchorMin} anchorMax={rt.anchorMax}" : "";
        result.Log("{0}{1} [{2}]{3}", indent, t.name, compList, rtInfo);
        for (int i = 0; i < t.childCount; i++)
        {
            PrintHierarchy(t.GetChild(i), indent + "  ", result);
        }
    }
}","Title":"Inspect SciFi_Menu_Canvas Hierarchy"}

