            string n = go.name.ToLower();
            if (n.Contains("scanline") || n.Contains("filter") || n.Contains("crt") || n.Contains("overlay") || n.Contains("cyberpunkhud") || n.Contains("kiroshi"))
            {
                result.Log("Found Candidate GO: {0} (Active: {1})", go.name, go.activeInHierarchy);
            }
        }
    }
}
"}

