using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string[] guids = AssetDatabase.FindAssets("t:Model");
        int countWithBlendShapes = 0;
        foreach (var guid in guids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            var assets = AssetDatabase.LoadAllAssetsAtPath(path);
            foreach (var a in assets)
            {
                if (a is UnityEngine.Mesh m && m.blendShapeCount > 0)
                {
                    countWithBlendShapes++;
                    if (countWithBlendShapes <= 20)
                    {
                        result.Log("Mesh with blendshapes: '{0}' in '{1}' ({2} shapes)", m.name, path, m.blendShapeCount);
                    }
                }
            }
        }
        result.Log("Total Meshes with blendshapes: {0}", countWithBlendShapes);
    }
}","Title":"Find All Meshes with BlendShapes"}

