internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var player = GameObject.FindWithTag("Player");
        if (player == null)
        {
            result.LogError("No player found!");
            return;
        }

        Vector3 pPos = player.transform.position;
        result.Log("Player position: {0}, rot: {1}", pPos, player.transform.eulerAngles);

        // Find all colliders or characters nearby
        Collider[] cols = Physics.OverlapSphere(pPos, 25f);
        result.Log("Colliders nearby: {0}", cols.Length);
        HashSet<string> nearbyCharacters = new HashSet<string>();
        foreach (var c in cols)
        {
            var root = c.transform.root.gameObject;
            if (root != player && (root.GetComponent<Animator>() != null || root.GetComponent<PolygonCyberCity.NPC.Spawner.CyberNPCController>() != null || root.name.Contains("Chr") || root.name.Contains("NPC")))
            {
                if (nearbyCharacters.Add(root.name))
                {
                    result.Log(" - Nearby character: {0} at {1} (dist: {2:F1}m)", root.name, root.transform.position, Vector3.Distance(pPos, root.transform.position));
                }
            }
        }
    }
}
