using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var player = GameObject.FindWithTag("Player");
        if (player == null) return;
        Vector3 pPos = player.transform.position;

        RaycastHit[] hits = Physics.RaycastAll(pPos + Vector3.up * 0.5f, Vector3.down, 10f);
        foreach (var h in hits)
        {
            if (h.collider.gameObject != player && !h.collider.transform.IsChildOf(player.transform))
            {
                result.Log("Ground below player (excluding player): point={0}, obj={1}", h.point, h.collider.name);
            }
        }
    }
}
