        [MenuItem("CyberCity/NPC/Setup Talking Sidekick NPCs in Scene", priority = 1)]
        public static void SetupTalkingSidekickNPCs()
        {
            int configuredCount = 0;

            // 1. Configure "Combined Character" if present in scene
