internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var player = GameObject.FindWithTag("Player");
        if (player == null) return;
        Vector3 pPos = player.transform.position;

        Vector3[] checkPoints = new Vector3[]
        {
            pPos + player.transform.right * -1.8f, // Left of player
            pPos + player.transform.right * 1.8f,  // Right of player
            pPos + player.transform.forward * 2.2f + player.transform.right * -1.2f, // Forward-left
            pPos + player.transform.forward * 2.2f + player.transform.right * 1.2f   // Forward-right
