        var player = GameObject.FindWithTag("Player");
        if (player == null)
        {
            var pScript = Object.FindAnyObjectByType<CyberpunkController>();
            if (pScript != null) player = pScript.gameObject;
        }

        if (player != null)
        {
            result.Log("Player found: {0} at position: {1}", player.name, player.transform.position);
        }
        else
        {
            result.Log("Player with tag 'Player' not found in hierarchy, scanning all GameObjects...");
            foreach (var go in Object.FindObjectsByType<GameObject>(FindObjectsSortMode.None))
