                if (go.name.ToLower().Contains("player") || go.name.ToLower().Contains("hero") || go.name.ToLower().Contains("alita"))
                {
                    result.Log("  Potential player: {0} at {1}", go.name, go.transform.position);
                }
            }
        }
    }
}
