internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var player = GameObject.Find("PF_PolygonPlayer");
        Vector3 p = player.transform.position;
        // Test positions 2.5m, 3.5m in front and slightly to left/right
        Vector3[] offsets = new Vector3[]
        {
            player.transform.forward * 2.5f,
            player.transform.forward * 3.5f,
            player.transform.forward * 3.0f + player.transform.right * 1.5f,
            player.transform.forward * 3.0f - player.transform.right * 1.5f,
            player.transform.forward * 4.0f - player.transform.right * 1.8f,
            player.transform.forward * 4.0f + player.transform.right * 1.8f
        };

        for (int i = 0; i < offsets.Length; i++)
        {
            Vector3 test = p + offsets[i] + Vector3.up * 2f;
            if (Physics.Raycast(test, Vector3.down, out RaycastHit hit, 10f))
            {
                result.Log("Offset {0}: ground at {1}, obj: {2}", i, hit.point, hit.collider.gameObject.name);
            }
        }
    }
}
