{"Code":"using UnityEngine;
using UnityEditor;
using System.Collections.Generic;
using System.Linq;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var trainsRoot = GameObject.Find("Trains");
        if (trainsRoot == null)
        {
            result.LogError("No 'Trains' root found");
            return;
        }

        List<Transform> trainVehicles = new List<Transform>();
        List<Transform> railPieces = new List<Transform>();

        foreach (Transform child in trainsRoot.transform)
        {
            string n = child.name;
            if (n.Contains("Veh_Train"))
            {
                trainVehicles.Add(child);
            }
            else if (n.Contains("Rail_Straight") || n.Contains("Rail_Curve") || n.Contains("Rail_Connector"))
            {
                railPieces.Add(child);
            }
        }

        result.Log("Found {0} train vehicle parts and {1} rail track pieces under 'Trains' root.", trainVehicles.Count, railPieces.Count);

        // Group train vehicle parts
        foreach (var v in trainVehicles)
        {
            result.Log("Vehicle: {0} at pos={1}, rot={2}", v.name, v.position, v.eulerAngles);
        }

        // Group rails by approximate Y level (rounded to nearest 1m)
        var railsByY = railPieces.GroupBy(r => Mathf.RoundToInt(r.position.y)).OrderByDescending(g => g.Key);
        foreach (var g in railsByY)
        {
            result.Log("Track Level Y ~ {0}m: {1} pieces (min pos: {2}, max pos: {3})", 
                g.Key, 
                g.Count(), 
                g.Select(p => p.position).Aggregate(Vector3.Min), 
                g.Select(p => p.position).Aggregate(Vector3.Max));
        }
    }
}","Title":"Analyze rail circuits and train vehicles"}

