using UnityEditor;
using UnityEditor.SceneManagement;
using Cyberpunk.Audio;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        AssetDatabase.Refresh();

        AudioClip clip = AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Audio/Music/448_Checkpoint_Omega.mp3");
        if (clip == null)
        {
            result.LogError("Could not find AudioClip at Assets/Audio/Music/448_Checkpoint_Omega.mp3");
            return;
        }

        GameObject bgmObj = GameObject.Find("[BGM_Controller]");
        if (bgmObj == null)
        {
            bgmObj = new GameObject("[BGM_Controller]");
            result.RegisterObjectCreation(bgmObj);
            result.Log("Created new GameObject '[BGM_Controller]'");
        }
        else
        {
            result.RegisterObjectModification(bgmObj);
        }

        CyberBackgroundMusic bgm = bgmObj.GetComponent<CyberBackgroundMusic>();
        if (bgm == null)
        {
            bgm = bgmObj.AddComponent<CyberBackgroundMusic>();
        }

        bgm.musicClip = clip;
        bgm.volume = 0.45f;
        bgm.fadeInDuration = 2.0f;
        bgm.loop = true;
        bgm.playOnAwake = true;
        bgm.SetupAudioSource();

        EditorUtility.SetDirty(bgmObj);
        EditorSceneManager.MarkSceneDirty(bgmObj.scene);

        result.Log("Successfully configured CyberBackgroundMusic on [BGM_Controller] with clip '{0}'!", clip.name);
    }
}
