{"Code":"using UnityEngine;
using UnityEditor;
using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // Find train cars in scene
        var cockpits = new List<Transform>();
        var middles = new List<Transform>();

        foreach (var obj in Object.FindObjectsByType<Transform>(FindObjectsSortMode.None))
        {
            if (obj.name.StartsWith("SM_Veh_Train_Cockpit")) cockpits.Add(obj);
            else if (obj.name.StartsWith("SM_Veh_Train_Middle")) middles.Add(obj);
        }

        result.Log("Found {0} Cockpits and {1} Middle cars", cockpits.Count, middles.Count);
        foreach (var c in cockpits)
        {
            result.Log("Cockpit: '{0}', Pos: {1}, Parent: {2}", c.name, c.position, c.parent != null ? c.parent.name : "root");
        }
        foreach (var m in middles)
        {
            result.Log("Middle: '{0}', Pos: {1}, Parent: {2}", m.name, m.position, m.parent != null ? m.parent.name : "root");
        }
    }
}
