    public void Execute(ExecutionResult result)
    {
        CyberCityTrainManager mgr = CyberCityTrainManager.Instance;
        if (mgr == null)
        {
            mgr = Object.FindAnyObjectByType<CyberCityTrainManager>();
        }

        if (mgr == null || mgr.trainFleet.Count == 0)
        {
            result.LogError("CyberCityTrainManager not ready");
            return;
        }

        // Test simulate 120 steps (2 seconds at 60 fps)
        float dt = 1f / 60f;
        for (int i = 0; i < 120; i++)
        {
            foreach (var t in mgr.trainFleet)
            {
                if (t.consist != null)
                {
                    // Access update logic
                    t.consist.SendMessage("Update", SendMessageOptions.DontRequireReceiver);
                }
            }
        }

        foreach (var t in mgr.trainFleet)
        {
            if (t.consist != null)
            {
                result.Log("Train '{0}': Speed={1:F2}m/s, State={2}, Cockpit pos={3}, Dir={4}",
                    t.lineName, t.consist.CurrentSpeed, t.consist.State, t.consist.cockpit.position, t.consist.TravelDirection);
            }
        }

        result.Log("Simulation step completed smoothly with zero errors!");
    }
}
