internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string[] animGuids = AssetDatabase.FindAssets("t:AnimationClip");
        result.Log("Total AnimationClips in project: {0}", animGuids.Length);

        string[] keywords = new string[] { "cheer", "clap", "crowd", "spectator", "taunt", "victory", "celebrat", "win", "wave", "dance", "talk", "idle", "shout", "hyped" };

        foreach (var guid in animGuids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            string lower = path.ToLower();
            if (keywords.Any(k => lower.Contains(k)))
            {
                var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(path);
                if (clip != null)
                {
                    result.Log("AnimClip: {0} -> {1}", clip.name, path);
                }
            }
        }
    }
}
