{"Code":"using UnityEngine;
using UnityEditor;
using System.Linq;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string[] fbxGuids = AssetDatabase.FindAssets("t:Model");
        int count = 0;
        foreach (var guid in fbxGuids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            var assets = AssetDatabase.LoadAllAssetsAtPath(path);
            foreach (var a in assets)
            {
                if (a is AnimationClip clip && !clip.name.StartsWith("__preview__"))
                {
                    string n = clip.name.ToLower();
                    if (n.Contains("cheer") || n.Contains("clap") || n.Contains("wave") || n.Contains("taunt") || 
                        n.Contains("victory") || n.Contains("posture") || n.Contains("shout") || n.Contains("point") ||
                        n.Contains("lean") || n.Contains("drink") || n.Contains("phone") || n.Contains("dance"))
                    {
                        count++;
                        if (count <= 50)
                        {
                            result.Log("SubClip: [{0}] in [{1}]", clip.name, path);
                        }
                    }
                }
            }
        }
        result.Log("Total matched animation clips inside FBXs: {0}", count);
    }
}
","Title":"Find Animation Clips inside FBX models"}

