{"Code":"using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // Adjust directional lights
        var dirMain = GameObject.Find("Stadium_Overhead_Broadcast_KeyLight");
        if (dirMain != null) dirMain.GetComponent<Light>().intensity = 0.95f;

        var dirRim = GameObject.Find("Stadium_Rim_Contrast_KeyLight");
        if (dirRim != null) dirRim.GetComponent<Light>().intensity = 0.45f;

        // Adjust ring spotlights
        var ringSpots = GameObject.FindObjectsByType<Light>(FindObjectsSortMode.None);
        foreach (var l in ringSpots)
        {
            if (l.name.Contains("Ring_Canvas_Spotlight"))
            {
                l.intensity = 8.0f;
            }
            if (l.name.Contains("Jumbotron_Downlight_Point"))
            {
                l.intensity = 5.0f;
            }
        }

        // Adjust ring platform material to dark carbon
        var stage = GameObject.Find("Raised_Ring_Stage_Platform");
        if (stage != null)
        {
            var rend = stage.GetComponent<Renderer>();
            var litShader = Shader.Find("Universal Render Pipeline/Lit") ?? Shader.Find("Standard");
            var mat = new Material(litShader);
            mat.color = new Color(0.08f, 0.10f, 0.14f);
            mat.SetFloat("_Smoothness", 0.35f);
            rend.sharedMaterial = mat;
        }

        result.Log("Balanced lighting and dark carbon ring canvas applied!");
    }
}
