{"Code":"using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;
using System.Text;
using System.Collections.Generic;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        Scene cityScene = SceneManager.GetActiveScene();
        StringBuilder sb = new StringBuilder();
        sb.AppendLine("Active Scene: " + cityScene.name);

        // Find doors or shop fronts in Demo_City
        var allRenderers = Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None);
        List<GameObject> doorObjects = new List<GameObject>();
        foreach (var r in allRenderers)
        {
            if (r.name.Contains("Door") || r.name.Contains("Shop") || r.name.Contains("Entrance"))
            {
                doorObjects.Add(r.gameObject);
            }
        }
        sb.AppendLine(string.Format("Found {0} door/shop objects in Demo_City. Showing first 25:", doorObjects.Count));
        for (int i = 0; i < Mathf.Min(doorObjects.Count, 25); i++)
        {
            var d = doorObjects[i];
            sb.AppendLine(string.Format("  - '{0}' at pos {1} (parent: {2})", d.name, d.transform.position, d.transform.parent != null ? d.transform.parent.name : "root"));
        }

        // Also check if there's any Player or SpawnPoint in Demo_City
        var player = GameObject.FindWithTag("Player");
        sb.AppendLine("Player found: " + (player != null ? player.name + " at " + player.transform.position : "null"));

        result.Log(sb.ToString());
    }
}
