            ("WeaponStore", new Vector3(6.5f, -199.0f, -10.5f)),
            ("ShootingRange", new Vector3(20.4f, -199.0f, 3.5f)),
            ("HackerDen", new Vector3(1.5f, -199.0f, 3.5f)),
            ("ConvenienceStore", new Vector3(-38.0f, -199.0f, 2.5f)),
            ("Apartment", new Vector3(-10.0f, -199.0f, 0.5f)),
            ("MicroPod", new Vector3(-2.5f, -199.0f, -10.0f)),
            ("Penthouse", new Vector3(-21.0f, -199.0f, -10.5f)),
        };

        foreach (var r in roomPositions)
        {
            if (Physics.Raycast(r.testPos, Vector3.down, out RaycastHit hit, 5f))
