                sb.AppendLine(string.Format("{0}: hit floor '{1}' at Y = {2:F2}", r.name, hit.collider.name, hit.point.y));
            }
            else
            {
                sb.AppendLine(string.Format("{0}: MISSED! No floor below {1}", r.name, r.testPos));
            }
        }

        result.Log(sb.ToString());
    }
}
