internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        string arenaPath = "Assets/Scenes/InsaneGun_Combat_TestArena.unity";
        Scene arenaScene = EditorSceneManager.OpenScene(arenaPath, OpenSceneMode.Additive);

        StringBuilder sb = new StringBuilder();
        sb.AppendLine("Root objects in InsaneGun_Combat_TestArena.unity:");
        foreach (var go in arenaScene.GetRootGameObjects())
        {
            sb.AppendLine(string.Format("- '{0}' (active={1}, pos={2}, childCount={3})", 
                go.name, go.activeSelf, go.transform.position, go.transform.childCount));
            for (int i = 0; i < go.transform.childCount; i++)
            {
                var ch = go.transform.GetChild(i);
                if (ch.name.ToLower().Contains("blackwall") || ch.name.ToLower().Contains("mirror") || ch.name.ToLower().Contains("barrier"))
                {
                    sb.AppendLine(string.Format("    * '{0}' (pos={1})", ch.name, ch.position));
                }
            }
        }

        EditorSceneManager.CloseScene(arenaScene, true);
        result.Log(sb.ToString());
    }
}
