    public void Execute(ExecutionResult result)
    {
        // Let's check where the open courtyard in front of the base is:
        // In the overview screenshot earlier, the courtyard was right in front of the big dome!
        var mainDome = GameObject.Find("SM_Bld_Pod_Research_07");
        if (mainDome == null)
        {
            var all = Object.FindObjectsByType<GameObject>(FindObjectsSortMode.None);
            foreach (var go in all)
            {
                if (go.name.Contains("Pod_Research_07") || go.name.Contains("Dome"))
                {
                    result.Log($"Dome found: {go.name} at {go.transform.position}");
                    mainDome = go;
                    break;
                }
            }
        }
        else
