{"Code":"using UnityEngine;
using UnityEditor;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        // Let's list the top-level buildings and terrain structures in Scene_Moon_Battle_Flashback
        var bld = GameObject.Find("Building");
        if (bld != null)
        {
            result.Log($"Building root child count: {bld.transform.childCount}");
            for (int i = 0; i < Mathf.Min(12, bld.transform.childCount); i++)
            {
                var c = bld.transform.GetChild(i);
                result.Log($"   Building {i}: {c.name} at {c.position}");
            }
        }

        // Let's find any large walls or towers
        var all = Object.FindObjectsByType<GameObject>(FindObjectsSortMode.None);
        int wallCount = 0;
        foreach (var go in all)
        {
            string n = go.name.ToLower();
            if (n.Contains("wall") || n.Contains("tower") || n.Contains("gate") || n.Contains("corridor"))
            {
                if (wallCount < 10)
                {
                    result.Log($"Wall/Tower: {go.name} at {go.transform.position}");
                    wallCount++;
                }
            }
        }
    }
}
