        private static Transform FindBone(Transform current, params string[] boneNames)
        {
            string lowerName = current.name.ToLower();
            foreach (var b in boneNames)
            {
                if (lowerName.Contains(b)) return current;
            }

            for (int i = 0; i < current.childCount; i++)
            {
                var found = FindBone(current.GetChild(i), boneNames);
                if (found != null) return found;
            }
            return null;
        }"

