{"Code":"using UnityEngine;
using UnityEditor;
using Alita;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        var director = Object.FindFirstObjectByType<AlitaMoonBattleCutsceneDirector>();
        var earth = GameObject.Find("Earth_In_Lunar_Sky");
        var cam = director.cinematicCamera;

        float[] times = new float[] { 3f, 12f, 21f, 30f, 39f, 48f };
        for (int i = 0; i < times.Length; i++)
        {
            director.ScrubTo(times[i]);
            Vector3 vp = cam.WorldToViewportPoint(earth.transform.position);
            result.Log("At t={0}s (Shot {1}): Cam pos={2}, Cam rot={3}, FOV={4}, Earth Viewport={5}",
                times[i], i + 1, cam.transform.position, cam.transform.rotation.eulerAngles, cam.fieldOfView, vp);
        }
    }
}
