        };

        for (int i = 0; i < texPaths.Length; i++)
        {
            var tex = AssetDatabase.LoadAssetAtPath<Texture2D>(texPaths[i]);
            if (tex != null)
            {
                // To read pixels, check if readable or use temporary render texture
                var rt = RenderTexture.GetTemporary(tex.width, tex.height);
                Graphics.Blit(tex, rt);
                var prev = RenderTexture.active;
                RenderTexture.active = rt;
                var readable = new Texture2D(32, 32, TextureFormat.RGB24, false);
                readable.ReadPixels(new Rect(0, 0, 32, 32), 0, 0);
                readable.Apply();
                RenderTexture.active = prev;
                RenderTexture.ReleaseTemporary(rt);

                Color avg = Color.black;
                for (int x = 0; x < 32; x++)
                    for (int y = 0; y < 32; y++)
                        avg += readable.GetPixel(x, y);
                avg /= (32f * 32f);

                result.Log("Texture {0}: avg color R={1:F2}, G={2:F2}, B={3:F2}",
                    tex.name, avg.r, avg.g, avg.b);

                Object.DestroyImmediate(readable);
            }
        }
    }
}
